fn main() {
    let store = Store::open("table.txt");
    let mut router = Router::new();
    router.add("log", Box::new(LogSink { written: 0 }));
    router.add("drop", Box::new(DropSink));

    for line in store.raw.lines() {
        if let Some((key, value)) = parse_line(line) {
            match router.route(&key, &value) {
                Ok(()) => {}
                Err(reason) => eprintln!("dropped: {}", reason),
            }
        }
    }

    // A macro with a call inside: the argument is a TOKEN TREE, so the
    // call is invisible to a tree walk and the node is flagged instead.
    println!("routed {} of {}", router.count, line_count(&store.raw));
    // A macro with no call inside: nothing to flag.
    println!("done");

    process::exit(0)
}

pub trait Sink {
    fn deliver(&mut self, payload: &str) -> Result<(), String>;
}

pub struct LogSink {
    pub written: usize,
}

fn deliver(&mut self, payload: &str) -> Result<(), String> {
        self.written += 1;
        println!("log: {}", payload);
        Ok(())
    }

fn deliver(&mut self, _payload: &str) -> Result<(), String> {
        Ok(())
    }

pub struct Router {
    sinks: HashMap<String, Box<dyn Sink>>,
    pub count: usize,
}

pub fn new() -> Router {
        Router { sinks: HashMap::new(), count: 0 }
    }

pub fn add(&mut self, name: &str, sink: Box<dyn Sink>) {
        self.sinks.insert(name.to_string(), sink);
    }

pub fn route(&mut self, name: &str, payload: &str) -> Result<(), String> {
        let sink = self.sinks.get_mut(name).ok_or_else(|| unknown_sink(name))?;
        self.count += 1;
        sink.deliver(payload)
    }

pub fn unknown_sink(name: &str) -> String {
    format!("no sink named {}", name)
}

pub fn parse_line(line: &str) -> Option<(String, String)> {
    let mut parts = line.splitn(2, ':');
    let key = parts.next()?;
    let value = parts.next()?;
    match key.trim() {
        "" => None,
        k => Some((k.to_string(), value.trim().to_string())),
    }
}

pub struct Store {
    pub raw: String,
}

pub fn open(path: &str) -> Store {
        let raw = fs::read_to_string(path).unwrap_or_default();
        Store { raw }
    }

fn routes_to_named_sink() {
    let mut router = Router::new();
    router.add("log", Box::new(LogSink { written: 0 }));
    let outcome = router.route("log", "hello");
    assert!(outcome.is_ok());
}

fn unknown_sink_errors() {
    let mut router = Router::new();
    let outcome = router.route("nope", "hello");
    assert!(outcome.is_err());
}
